// DO NOT EDIT: Code generated by "generate-jsdoc-example-tests".
import { expect, it } from "vitest";
import { createOAuthTokenRefresher, type Credential } from '@bedrock-rbx/ocale'

it('Example 1', () => {
  let saved = 'refresh-0'
  const getAccessToken = createOAuthTokenRefresher({
    clientId: 'client-id',
    fetch: async () =>
      Response.json({
        access_token: 'access-1',
        expires_in: 900,
        refresh_token: 'refresh-1',
      }),
    onRotate: (refreshToken) => {
      saved = refreshToken
    },
    refreshToken: saved,
  })
  const credential: Credential = {
    getAccessToken,
    identity: 'user-1',
    kind: 'oauth',
  }
  expect(credential.kind).toBe('oauth')
  return getAccessToken({ signal: new AbortController().signal }).then(
    (token) => {
      expect(token).toBe('access-1')
      expect(saved).toBe('refresh-1')
    },
  )
})
